import React, { useState, useEffect } from 'react';
import { 
  Bell,
  Search,
  Menu,
  Plus,
  Edit3,
  Trash2,
  Save,
  X,
  Users,
  Target,
  Zap,
  Award,
  Linkedin,
  Github,
  Mail,
  TrendingUp,
  Calendar,
  CheckCircle
} from 'lucide-react';
import Sidebar from '../Sidebar';
import { useAuth } from '../../context/AuthContext';

const iconMap = {
  Target, Zap, Award, Users
};

const AboutAdmin = () => {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [activeTab, setActiveTab] = useState('stats');
  const [stats, setStats] = useState([]);
  const [values, setValues] = useState([]);
  const [teamMembers, setTeamMembers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [modalType, setModalType] = useState('');
  const [editingItem, setEditingItem] = useState(null);
  const { API_URL } = useAuth();

  const [formData, setFormData] = useState({
    title: '',
    description: '',
    icon: 'Target',
    value: 0,
    suffix: '',
    name: '',
    role: '',
    initials: '',
    linkedin: '',
    github: '',
    email: ''
  });

  useEffect(() => {
    fetchAboutData();
  }, []);

  const fetchAboutData = async () => {
    try {
      const [statsRes, valuesRes, teamRes] = await Promise.all([
        fetch(`${API_URL}/about.php?type=stats`),
        fetch(`${API_URL}/about.php?type=values`),
        fetch(`${API_URL}/about.php?type=team`)
      ]);

      if (statsRes.ok) {
        const statsData = await statsRes.json();
        setStats(statsData.length > 0 ? statsData : [
          { id: 1, value: 15, suffix: '+', label: 'Projects Completed' },
          { id: 2, value: 4, suffix: '', label: 'Team Members' },
          { id: 3, value: 100, suffix: '%', label: 'Client Satisfaction' },
          { id: 4, value: 2, suffix: '+', label: 'Years Experience' }
        ]);
      }

      if (valuesRes.ok) {
        const valuesData = await valuesRes.json();
        setValues(valuesData.length > 0 ? valuesData : [
          { id: 1, icon: 'Target', title: 'Precision', description: 'We focus on delivering exactly what our clients need with attention to every detail.' },
          { id: 2, icon: 'Zap', title: 'Innovation', description: 'We embrace cutting-edge technologies to create modern, future-proof solutions.' },
          { id: 3, icon: 'Award', title: 'Quality', description: 'We never compromise on quality, ensuring robust and scalable applications.' },
          { id: 4, icon: 'Users', title: 'Collaboration', description: 'We work closely with our clients, keeping communication transparent throughout.' }
        ]);
      }

      if (teamRes.ok) {
        const teamData = await teamRes.json();
        setTeamMembers(teamData);
      }
    } catch (err) {
      console.error('Error fetching about data:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleNewItem = (type) => {
    setModalType(type);
    setEditingItem(null);
    setFormData({
      title: '',
      description: '',
      icon: 'Target',
      value: 0,
      suffix: '',
      name: '',
      role: '',
      initials: '',
      linkedin: '',
      github: '',
      email: ''
    });
    setShowModal(true);
  };

  const handleEditItem = (type, item) => {
    setModalType(type);
    setEditingItem(item);
    setFormData({
      title: item.title || item.label || '',
      description: item.description || '',
      icon: item.icon || 'Target',
      value: item.value || 0,
      suffix: item.suffix || '',
      name: item.name || '',
      role: item.role || '',
      initials: item.initials || '',
      linkedin: item.linkedin || item.socials?.linkedin || '',
      github: item.github || item.socials?.github || '',
      email: item.email || item.socials?.email || ''
    });
    setShowModal(true);
  };

  const handleDeleteItem = async (type, itemId) => {
    if (!window.confirm('Are you sure you want to delete this item?')) return;

    const endpoints = {
      stats: 'about_stats.php',
      values: 'about_values.php',
      team: 'about_team.php'
    };

    try {
      const response = await fetch(`${API_URL}/${endpoints[type]}`, {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id: itemId })
      });

      if (response.ok) {
        fetchAboutData();
      }
    } catch (err) {
      console.error('Delete error:', err);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const endpoints = {
      stats: 'about_stats.php',
      values: 'about_values.php',
      team: 'about_team.php'
    };

    const method = editingItem ? 'PUT' : 'POST';
    const body = editingItem 
      ? { ...formData, id: editingItem.id }
      : formData;

    try {
      const response = await fetch(`${API_URL}/${endpoints[modalType]}`, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body)
      });

      if (response.ok) {
        setShowModal(false);
        fetchAboutData();
      }
    } catch (err) {
      console.error('Submit error:', err);
    }
  };

  const tabs = [
    { id: 'stats', label: 'Statistics', icon: TrendingUp },
    { id: 'values', label: 'Company Values', icon: Award },
    { id: 'team', label: 'Team Members', icon: Users }
  ];

  const renderStatsTab = () => (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h3 className="text-xl font-semibold text-white">About Statistics</h3>
        <button
          onClick={() => handleNewItem('stats')}
          className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-xl hover:bg-blue-500 transition-colors text-sm font-medium"
        >
          <Plus className="w-4 h-4" />
          Add Stat
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {stats.map((stat) => (
          <div key={stat.id} className="bg-[#0f172a] rounded-2xl p-6 border border-white/5">
            <div className="flex items-center justify-between mb-4">
              <div className="p-3 rounded-xl bg-blue-500/10 text-blue-400">
                <TrendingUp className="w-6 h-6" />
              </div>
              <div className="flex gap-2">
                <button
                  onClick={() => handleEditItem('stats', stat)}
                  className="p-2 rounded-lg bg-white/5 text-gray-400 hover:text-white hover:bg-white/10 transition-colors"
                >
                  <Edit3 className="w-4 h-4" />
                </button>
                <button
                  onClick={() => handleDeleteItem('stats', stat.id)}
                  className="p-2 rounded-lg bg-white/5 text-red-400 hover:text-red-300 hover:bg-red-500/10 transition-colors"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>
            </div>
            <div className="text-3xl font-bold text-white mb-1">
              {stat.value}{stat.suffix}
            </div>
            <p className="text-gray-400 text-sm">{stat.label}</p>
          </div>
        ))}
      </div>
    </div>
  );

  const renderValuesTab = () => (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h3 className="text-xl font-semibold text-white">Company Values</h3>
        <button
          onClick={() => handleNewItem('values')}
          className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-xl hover:bg-blue-500 transition-colors text-sm font-medium"
        >
          <Plus className="w-4 h-4" />
          Add Value
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {values.map((value) => {
          const Icon = iconMap[value.icon] || Target;
          return (
            <div key={value.id} className="bg-[#0f172a] rounded-2xl p-6 border border-white/5">
              <div className="flex items-start justify-between">
                <div className="flex items-center gap-4">
                  <div className="p-3 rounded-xl bg-blue-500/10 text-blue-400">
                    <Icon className="w-6 h-6" />
                  </div>
                  <div>
                    <h4 className="text-lg font-semibold text-white">{value.title}</h4>
                    <p className="text-gray-400 text-sm mt-1">{value.description}</p>
                  </div>
                </div>
                <div className="flex gap-2 ml-4">
                  <button
                    onClick={() => handleEditItem('values', value)}
                    className="p-2 rounded-lg bg-white/5 text-gray-400 hover:text-white hover:bg-white/10 transition-colors"
                  >
                    <Edit3 className="w-4 h-4" />
                  </button>
                  <button
                    onClick={() => handleDeleteItem('values', value.id)}
                    className="p-2 rounded-lg bg-white/5 text-red-400 hover:text-red-300 hover:bg-red-500/10 transition-colors"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );

  const renderTeamTab = () => (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h3 className="text-xl font-semibold text-white">Team Members</h3>
        <button
          onClick={() => handleNewItem('team')}
          className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-xl hover:bg-blue-500 transition-colors text-sm font-medium"
        >
          <Plus className="w-4 h-4" />
          Add Member
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {teamMembers.map((member) => (
          <div key={member.id} className="bg-[#0f172a] rounded-2xl p-6 border border-white/5">
            <div className="flex items-start justify-between mb-4">
              <div className="flex items-center gap-4">
                <div className="w-14 h-14 rounded-full bg-gradient-to-br from-blue-500 to-blue-600 flex items-center justify-center text-white font-semibold text-lg">
                  {member.initials}
                </div>
                <div>
                  <h4 className="text-lg font-semibold text-white">{member.name}</h4>
                  <p className="text-blue-400 text-sm">{member.role}</p>
                </div>
              </div>
              <div className="flex gap-2">
                <button
                  onClick={() => handleEditItem('team', member)}
                  className="p-2 rounded-lg bg-white/5 text-gray-400 hover:text-white hover:bg-white/10 transition-colors"
                >
                  <Edit3 className="w-4 h-4" />
                </button>
                <button
                  onClick={() => handleDeleteItem('team', member.id)}
                  className="p-2 rounded-lg bg-white/5 text-red-400 hover:text-red-300 hover:bg-red-500/10 transition-colors"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>
            </div>
            <p className="text-gray-400 text-sm mb-4">{member.description}</p>
            <div className="flex gap-3">
              {member.linkedin && (
                <a href={member.linkedin} target="_blank" rel="noopener noreferrer" className="p-2 rounded-lg bg-white/5 text-blue-400 hover:text-blue-300 hover:bg-blue-500/10 transition-colors">
                  <Linkedin className="w-4 h-4" />
                </a>
              )}
              {member.github && (
                <a href={member.github} target="_blank" rel="noopener noreferrer" className="p-2 rounded-lg bg-white/5 text-gray-400 hover:text-white hover:bg-white/10 transition-colors">
                  <Github className="w-4 h-4" />
                </a>
              )}
              {member.email && (
                <a href={`mailto:${member.email}`} className="p-2 rounded-lg bg-white/5 text-red-400 hover:text-red-300 hover:bg-red-500/10 transition-colors">
                  <Mail className="w-4 h-4" />
                </a>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );

  const renderModal = () => {
    if (!showModal) return null;

    const isStats = modalType === 'stats';
    const isValues = modalType === 'values';
    const isTeam = modalType === 'team';

    return (
      <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
        <div className="bg-[#0f172a] rounded-2xl w-full max-w-md mx-auto border border-white/10" style={{ maxWidth: '75vw', transform: 'scale(0.8)', transformOrigin: 'center' }}>
          <div className="p-6 border-b border-white/5 flex items-center justify-between">
            <h3 className="text-lg font-semibold text-white">
              {editingItem ? 'Edit' : 'Add'} {isStats ? 'Statistic' : isValues ? 'Value' : 'Team Member'}
            </h3>
            <button
              onClick={() => setShowModal(false)}
              className="p-2 rounded-lg bg-white/5 text-gray-400 hover:text-white hover:bg-white/10 transition-colors"
            >
              <X className="w-5 h-5" />
            </button>
          </div>

          <form onSubmit={handleSubmit} className="p-6 space-y-4">
            {(isStats || isValues) && (
              <div>
                <label className="block text-sm font-medium text-gray-300 mb-2">
                  {isStats ? 'Label' : 'Title'}
                </label>
                <input
                  type="text"
                  value={formData.title}
                  onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                  className="w-full px-4 py-3 rounded-xl bg-white/5 border border-white/10 text-white text-sm focus:outline-none focus:border-blue-500"
                  placeholder={isStats ? 'e.g., Projects Completed' : 'e.g., Innovation'}
                  required
                />
              </div>
            )}

            {isTeam && (
              <>
                <div>
                  <label className="block text-sm font-medium text-gray-300 mb-2">Name</label>
                  <input
                    type="text"
                    value={formData.name}
                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    className="w-full px-4 py-3 rounded-xl bg-white/5 border border-white/10 text-white text-sm focus:outline-none focus:border-blue-500"
                    placeholder="Full Name"
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-300 mb-2">Role</label>
                  <input
                    type="text"
                    value={formData.role}
                    onChange={(e) => setFormData({ ...formData, role: e.target.value })}
                    className="w-full px-4 py-3 rounded-xl bg-white/5 border border-white/10 text-white text-sm focus:outline-none focus:border-blue-500"
                    placeholder="Job Title"
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-300 mb-2">Initials</label>
                  <input
                    type="text"
                    value={formData.initials}
                    onChange={(e) => setFormData({ ...formData, initials: e.target.value })}
                    className="w-full px-4 py-3 rounded-xl bg-white/5 border border-white/10 text-white text-sm focus:outline-none focus:border-blue-500"
                    placeholder="RA"
                    maxLength="2"
                  />
                </div>
              </>
            )}

            <div>
              <label className="block text-sm font-medium text-gray-300 mb-2">Description</label>
              <textarea
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                className="w-full px-4 py-3 rounded-xl bg-white/5 border border-white/10 text-white text-sm focus:outline-none focus:border-blue-500 resize-none"
                rows="3"
                placeholder="Enter description..."
                required
              />
            </div>

            {isStats && (
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-300 mb-2">Value</label>
                  <input
                    type="number"
                    value={formData.value}
                    onChange={(e) => setFormData({ ...formData, value: parseInt(e.target.value) || 0 })}
                    className="w-full px-4 py-3 rounded-xl bg-white/5 border border-white/10 text-white text-sm focus:outline-none focus:border-blue-500"
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-300 mb-2">Suffix</label>
                  <input
                    type="text"
                    value={formData.suffix}
                    onChange={(e) => setFormData({ ...formData, suffix: e.target.value })}
                    className="w-full px-4 py-3 rounded-xl bg-white/5 border border-white/10 text-white text-sm focus:outline-none focus:border-blue-500"
                    placeholder="+, %"
                  />
                </div>
              </div>
            )}

            {(isValues || isTeam) && (
              <div>
                <label className="block text-sm font-medium text-gray-300 mb-2">Icon</label>
                <select
                  value={formData.icon}
                  onChange={(e) => setFormData({ ...formData, icon: e.target.value })}
                  className="w-full px-4 py-3 rounded-xl bg-white/5 border border-white/10 text-white text-sm focus:outline-none focus:border-blue-500"
                >
                  <option value="Target">Target</option>
                  <option value="Zap">Zap</option>
                  <option value="Award">Award</option>
                  <option value="Users">Users</option>
                </select>
              </div>
            )}

            {isTeam && (
              <>
                <div>
                  <label className="block text-sm font-medium text-gray-300 mb-2">LinkedIn URL</label>
                  <input
                    type="url"
                    value={formData.linkedin}
                    onChange={(e) => setFormData({ ...formData, linkedin: e.target.value })}
                    className="w-full px-4 py-3 rounded-xl bg-white/5 border border-white/10 text-white text-sm focus:outline-none focus:border-blue-500"
                    placeholder="https://linkedin.com/in/..."
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-300 mb-2">GitHub URL</label>
                  <input
                    type="url"
                    value={formData.github}
                    onChange={(e) => setFormData({ ...formData, github: e.target.value })}
                    className="w-full px-4 py-3 rounded-xl bg-white/5 border border-white/10 text-white text-sm focus:outline-none focus:border-blue-500"
                    placeholder="https://github.com/..."
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-300 mb-2">Email</label>
                  <input
                    type="email"
                    value={formData.email}
                    onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                    className="w-full px-4 py-3 rounded-xl bg-white/5 border border-white/10 text-white text-sm focus:outline-none focus:border-blue-500"
                    placeholder="email@example.com"
                  />
                </div>
              </>
            )}

            <div className="flex gap-3 pt-4">
              <button
                type="button"
                onClick={() => setShowModal(false)}
                className="flex-1 px-4 py-3 bg-white/5 text-white rounded-xl hover:bg-white/10 transition-colors text-sm font-medium"
              >
                Cancel
              </button>
              <button
                type="submit"
                className="flex-1 px-4 py-3 bg-blue-600 text-white rounded-xl hover:bg-blue-500 transition-colors text-sm font-medium"
              >
                {editingItem ? 'Update' : 'Add'}
              </button>
            </div>
          </form>
        </div>
      </div>
    );
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-[#0a1628] flex">
        <Sidebar sidebarOpen={sidebarOpen} setSidebarOpen={setSidebarOpen} />
        <main className="flex-1 min-w-0 flex items-center justify-center">
          <div className="animate-spin w-8 h-8 border-2 border-blue-500 border-t-transparent rounded-full" />
        </main>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#0a1628] flex">
      <Sidebar sidebarOpen={sidebarOpen} setSidebarOpen={setSidebarOpen} />

      {/* Main Content */}
      <main className="flex-1 min-w-0">
        {/* Header */}
        <header className="sticky top-0 z-20 bg-[#0a1628]/80 backdrop-blur-md border-b border-white/5 px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <button
                onClick={() => setSidebarOpen(true)}
                className="lg:hidden p-2 rounded-xl bg-white/5 text-gray-400 hover:text-white hover:bg-white/10 transition-colors"
              >
                <Menu className="w-5 h-5" />
              </button>
              <div>
                <h1 className="text-2xl font-bold text-white">About Management</h1>
                <p className="text-gray-400 text-sm">Manage your about page content</p>
              </div>
            </div>

            <div className="flex items-center gap-4">
              <button className="p-2 rounded-xl bg-white/5 text-gray-400 hover:text-white hover:bg-white/10 transition-colors">
                <Bell className="w-5 h-5" />
              </button>
            </div>
          </div>
        </header>

        {/* Tabs */}
        <div className="px-6 py-4 border-b border-white/5">
          <div className="flex gap-2">
            {tabs.map((tab) => {
              const Icon = tab.icon;
              return (
                <button
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id)}
                  className={`flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-medium transition-all ${
                    activeTab === tab.id
                      ? 'bg-blue-600 text-white'
                      : 'bg-white/5 text-gray-400 hover:text-white hover:bg-white/10'
                  }`}
                >
                  <Icon className="w-4 h-4" />
                  {tab.label}
                </button>
              );
            })}
          </div>
        </div>

        {/* Content */}
        <div className="p-6">
          {activeTab === 'stats' && renderStatsTab()}
          {activeTab === 'values' && renderValuesTab()}
          {activeTab === 'team' && renderTeamTab()}
        </div>
      </main>

      {renderModal()}
    </div>
  );
};

export default AboutAdmin;
